const SCENE_ORCHESTRATION_PHASE_LOG_TYPES = {
    queued: 'info',
    llm_submit: 'process',
    llm_returned: 'info',
    importing: 'process',
    imported: 'success',
    failed: 'error',
};

const deriveSceneOrchestrationPhase = (unit) => {
    if (!unit) return 'unknown';
    const explicit = String(unit.orchestration_phase || '').trim().toLowerCase();
    if (explicit) return explicit;
    const importStatus = String(unit.import_status || '').trim().toLowerCase();
    const parseStatus = String(unit.parse_status || '').trim().toLowerCase();
    if (importStatus === 'success') return 'imported';
    if (importStatus === 'importing') return 'importing';
    if (importStatus === 'awaiting_workspace_import') return 'llm_returned';
    if (importStatus === 'llm_returned') return 'llm_returned';
    if (importStatus === 'llm_running' || importStatus === 'running') return 'llm_submit';
    if (importStatus === 'failed' || parseStatus === 'failed') return 'failed';
    if (importStatus === 'queued') return 'queued';
    return importStatus || 'unknown';
};

const buildSceneOrchestrationPhaseMessage = (sceneId, phase, { sceneOrder, totalScenes, errorCode, t }) => {
    const orderLabel = sceneOrder && totalScenes ? ` (${sceneOrder}/${totalScenes})` : '';
    switch (phase) {
        case 'queued':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 已排队，等待提交 LLM...`,
                `[Scene beats] ${sceneId}${orderLabel} queued, waiting to submit to LLM...`
            );
        case 'llm_submit':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 已提交 LLM，等待返回...`,
                `[Scene beats] ${sceneId}${orderLabel} submitted to LLM, waiting for response...`
            );
        case 'llm_returned':
            return t(
                `[场景编排] ${sceneId}${orderLabel} LLM 已返回，校验通过`,
                `[Scene beats] ${sceneId}${orderLabel} LLM returned and passed validation`
            );
        case 'importing':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 正在导入工作区...`,
                `[Scene beats] ${sceneId}${orderLabel} importing into workspace...`
            );
        case 'imported':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 导入完成`,
                `[Scene beats] ${sceneId}${orderLabel} import completed`
            );
        case 'failed': {
            let detail = String(errorCode || '').trim();
            if (detail.startsWith('SCENE_MARKDOWN_MISSING_BEAT_1')) {
                return t(
                    `[场景编排] ${sceneId}${orderLabel} 跳过：输入无 Beat 1，场景不对`,
                    `[Scene beats] ${sceneId}${orderLabel} skipped: no Beat 1 in input (invalid scene)`
                );
            }
            if (detail.startsWith('SCENE_MARKDOWN_SCENE_ID_MISMATCH')) {
                const expectedMatch = detail.match(/expected=([^,]+)/i);
                const gotMatch = detail.match(/got=([^,]+)/i);
                const expectedId = expectedMatch?.[1] || sceneId;
                const gotId = gotMatch?.[1] || '';
                return t(
                    `[场景编排] ${sceneId}${orderLabel} 失败：返回 Scene ID 与期望不一致（期望 ${expectedId}${gotId ? `，实际 ${gotId}` : ''}）`,
                    `[Scene beats] ${sceneId}${orderLabel} failed: returned Scene ID mismatch (expected ${expectedId}${gotId ? `, got ${gotId}` : ''})`
                );
            }
            return t(
                `[场景编排] ${sceneId}${orderLabel} 失败${detail ? `：${detail}` : ''}`,
                `[Scene beats] ${sceneId}${orderLabel} failed${detail ? `: ${detail}` : ''}`
            );
        }
        default:
            return '';
    }
};

const createSceneOrchestrationPanelReporter = ({ totalScenes = 1, t }) => {
    const importedScenes = new Set();
    const reportedPhases = new Map();
    const resolvedTotal = Math.max(1, Number(totalScenes) || 1);

    const formatOrderLabel = (sceneOrder, total) => (
        sceneOrder && total ? ` (${sceneOrder}/${total})` : ''
    );

    const buildHighlightHint = (sceneId, phase, sceneOrder, total) => {
        const orderLabel = formatOrderLabel(sceneOrder, total);
        switch (phase) {
            case 'queued':
                return t(
                    `「${sceneId}」已排队${orderLabel}`,
                    `"${sceneId}" queued${orderLabel}`
                );
            case 'llm_submit':
                return t(
                    `「${sceneId}」已提交 AI 引擎${orderLabel}`,
                    `"${sceneId}" submitted to AI engine${orderLabel}`
                );
            case 'llm_returned':
                return t(
                    `「${sceneId}」AI 已返回并校验通过${orderLabel}`,
                    `"${sceneId}" AI response validated${orderLabel}`
                );
            case 'importing':
                return t(
                    `「${sceneId}」正在入库${orderLabel}`,
                    `"${sceneId}" importing into workspace${orderLabel}`
                );
            case 'imported':
                return t(
                    `「${sceneId}」已入库，可在场景页查看${orderLabel}`,
                    `"${sceneId}" imported — open Scenes tab${orderLabel}`
                );
            case 'failed':
                return t(
                    `「${sceneId}」处理失败${orderLabel}`,
                    `"${sceneId}" failed${orderLabel}`
                );
            default:
                return '';
        }
    };

    const buildAggregateMessage = (total) => {
        const imported = importedScenes.size;
        const totalCount = Math.max(resolvedTotal, Number(total) || 0, imported);
        const labels = [...importedScenes].sort().join('、');
        if (imported >= totalCount && totalCount > 0) {
            return t(
                `✅ 场景编排已完成 (${imported}/${totalCount}${labels ? `：${labels}` : ''})`,
                `Scene orchestration completed (${imported}/${totalCount}${labels ? `: ${labels.replace(/、/g, ', ')}` : ''})`
            );
        }
        return t(
            `场景编排进行中 (${imported}/${totalCount} 已入库${labels ? `：${labels}` : ''})...`,
            `Scene orchestration in progress (${imported}/${totalCount} imported${labels ? `: ${labels.replace(/、/g, ', ')}` : ''})...`
        );
    };

    return {
        report({ sceneId, phase, sceneOrder, totalScenes: totalOverride, errorCode }) {
            const stableSceneId = String(sceneId || '').trim();
            const stablePhase = String(phase || '').trim().toLowerCase();
            if (!stableSceneId || !stablePhase) return null;

            const reported = reportedPhases.get(stableSceneId) || new Set();
            if (reported.has(stablePhase)) return null;
            reported.add(stablePhase);
            reportedPhases.set(stableSceneId, reported);

            const total = Math.max(resolvedTotal, Number(totalOverride) || 0, importedScenes.size);
            if (stablePhase === 'imported') importedScenes.add(stableSceneId);

            if (stablePhase === 'failed') {
                return {
                    phase: 'warning',
                    message: buildSceneOrchestrationPhaseMessage(stableSceneId, stablePhase, {
                        sceneOrder,
                        totalScenes: total,
                        errorCode,
                        t,
                    }),
                    highlightHint: buildHighlightHint(stableSceneId, stablePhase, sceneOrder, total),
                };
            }

            return {
                phase: 'scene_beats',
                message: buildAggregateMessage(total),
                highlightHint: buildHighlightHint(stableSceneId, stablePhase, sceneOrder, total),
            };
        },
    };
};

const resolveEpisodeSceneIdPrefix = (episode, scriptText = '') => {
    const text = String(scriptText || '');
    for (const pattern of [
        /\b(EP\d+)_SC\d+\b/i,
        /\[SCENE_START:(EP\d+)_SC\d+\]/i,
        /\|\s*(EP\d+)\s*\|\s*EP\d+_SC\d+\s*\|/i,
    ]) {
        const match = text.match(pattern);
        if (match?.[1]) return String(match[1]).trim().toUpperCase();
    }

    const info = episode?.episode_info && typeof episode.episode_info === 'object'
        ? episode.episode_info
        : {};
    for (const key of ['episode_script_episode_number', 'story_dna_episode_number', 'episode_number', 'index']) {
        const n = Number(info[key]);
        if (Number.isFinite(n) && n > 0) return `EP${String(Math.floor(n)).padStart(2, '0')}`;
    }

    const title = String(episode?.title || '');
    for (const pattern of [/EP\s*(\d+)/i, /第\s*(\d+)\s*集/, /^(\d+)\s*[-_.]/]) {
        const match = title.match(pattern);
        if (match?.[1]) {
            const n = Number(match[1]);
            if (Number.isFinite(n) && n > 0) return `EP${String(Math.floor(n)).padStart(2, '0')}`;
        }
    }

    const parsedEpisodeNumber = parseEpisodeNumberFromText(title);
    if (Number.isFinite(parsedEpisodeNumber) && parsedEpisodeNumber > 0) {
        return `EP${String(Math.floor(parsedEpisodeNumber)).padStart(2, '0')}`;
    }
    return 'EP01';
};

const canonicalizeSceneUnitId = (sceneId, sceneOrder, episodePrefix) => {
    const sid = String(sceneId || '').trim();
    const prefix = String(episodePrefix || 'EP01').trim().toUpperCase();
    const order = Math.max(1, Number(sceneOrder) || 0);
    if (/^[A-Za-z]+\d+_SC/i.test(sid)) return sid;
    if (/^\d+$/.test(sid)) return `${prefix}_SC${String(Number(sid)).padStart(2, '0')}`;
    const scMatch = sid.match(/^SC?(\d+)$/i);
    if (scMatch) return `${prefix}_SC${String(Number(scMatch[1])).padStart(2, '0')}`;
    const trailing = sid.match(/(\d+)\s*$/);
    if (trailing && sid.length <= 8) return `${prefix}_SC${String(Number(trailing[1])).padStart(2, '0')}`;
    return sid || `${prefix}_SC${String(order).padStart(2, '0')}`;
};

const applyCanonicalSceneIdsToUnits = (units, episodePrefix) => (
    (Array.isArray(units) ? units : []).map((unit, idx) => {
        const order = Number(unit?.sceneOrder) || idx + 1;
        const newId = canonicalizeSceneUnitId(unit?.sceneId, order, episodePrefix);
        if (newId === unit?.sceneId) {
            return { ...unit, sceneOrder: order };
        }
        return {
            ...unit,
            sceneId: newId,
            sceneOrder: order,
            markerStartToken: `[SCENE_START:${newId}]`,
            markerEndToken: `[SCENE_END:${newId}]`,
        };
    })
);

const sceneIdHasLetterSuffix = (sceneId) => (
    /^EP\d+_SC\d+[A-Za-z]+$/i.test(String(sceneId || '').trim())
);

const normalizeSceneIdToken = (value) => (
    String(value || '').trim().toLowerCase().replace(/[\s_\-./]+/g, '')
);

const deriveSceneOrderFromSceneId = (sceneId) => {
    const sid = String(sceneId || '').trim();
    if (!sid) return null;
    const suffixMatch = sid.match(/^EP\d+_SC(\d+)[A-Za-z]+$/i);
    if (suffixMatch) {
        const order = Number(suffixMatch[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    const canonicalMatch = sid.match(/^EP\d+_SC(\d+)$/i);
    if (canonicalMatch) {
        const order = Number(canonicalMatch[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    if (/^\d+$/.test(sid)) {
        const order = Number(sid);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    const scMatch = sid.match(/^SC?(\d+)$/i);
    if (scMatch) {
        const order = Number(scMatch[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    const trailing = sid.match(/(\d+)\s*$/);
    if (trailing && sid.length <= 12) {
        const order = Number(trailing[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    return null;
};

const findDbSceneByPatchSceneId = (dbScenes, patchSceneId) => {
    const patchToken = normalizeSceneIdToken(patchSceneId);
    if (!patchToken) return null;
    const rows = Array.isArray(dbScenes) ? dbScenes : [];
    // Prefer exact Scene ID / scene_no / scene_code token match.
    const exact = rows.find((row) => (
        [row?.scene_no, row?.scene_id, row?.scene_code]
            .map(normalizeSceneIdToken)
            .some((token) => token && token === patchToken)
    ));
    if (exact) return exact;

    // Same episode scene number aliases: EP01_SC03 ↔ "3" / "03".
    // Letter-suffix IDs stay exact-only so SC03A never steals SC03.
    if (sceneIdHasLetterSuffix(patchSceneId)) return null;
    const patchOrder = deriveSceneOrderFromSceneId(patchSceneId);
    if (!(Number.isFinite(patchOrder) && patchOrder > 0)) return null;
    return rows.find((row) => {
        const candidates = [row?.scene_no, row?.scene_id, row?.scene_code];
        return candidates.some((raw) => {
            if (!String(raw || '').trim()) return false;
            if (sceneIdHasLetterSuffix(raw)) return false;
            const order = deriveSceneOrderFromSceneId(raw);
            return Number.isFinite(order) && order > 0 && order === patchOrder;
        });
    }) || null;
};

const dbSceneMatchesPatchSceneId = (dbScenes, patchSceneId) => (
    !!findDbSceneByPatchSceneId(dbScenes, patchSceneId)
);

const resolveImportedDbSceneIdFromReport = (importReport, markerSceneId) => {
    const rows = [
        ...(Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows : []),
        ...(Array.isArray(importReport?.scenes) ? importReport.scenes : []),
    ];
    const markerToken = normalizeSceneIdToken(markerSceneId);
    if (!markerToken) return null;
    for (const row of rows) {
        const id = Number(row?.id || 0);
        if (!Number.isFinite(id) || id <= 0) continue;
        const tokens = [row?.scene_no, row?.scene_id, row?.scene_code]
            .map(normalizeSceneIdToken)
            .filter(Boolean);
        if (tokens.some((token) => token === markerToken)) return id;
    }
    // No single-row fallback: a leftover importReport must not bind the wrong scene.
    return null;
};

const filterDbScenesByCanonicalMarkers = (dbScenes, canonicalMarkers) => {
    const rows = Array.isArray(dbScenes) ? dbScenes : [];
    const markers = Array.isArray(canonicalMarkers)
        ? canonicalMarkers
        : (canonicalMarkers instanceof Set ? [...canonicalMarkers] : []);
    const allowed = new Set(
        markers
            .map((item) => normalizeSceneIdToken(item))
            .filter(Boolean)
    );
    if (!allowed.size) return rows;
    return rows.filter((row) => (
        [row?.scene_no, row?.scene_id, row?.scene_code]
            .map(normalizeSceneIdToken)
            .some((token) => token && allowed.has(token))
    ));
};

const EMPTY_STORYBOARD_TASK_PROGRESS = {
    started: 0,
    completed: 0,
    failed: 0,
    running: 0,
    items: {},
};

/** True when a storyboard item failed solely because scene-linked ENV design was not ready yet. */
const isStoryboardBlockedOnEnvDesignError = (error) => (
    /本场关联环境 ENV 尚未完成资产设计|Scene-linked ENV asset design incomplete/i.test(
        String(error || '')
    )
);

const normalizeStoryboardTaskProgress = (value) => {
    if (!value || typeof value !== 'object') return EMPTY_STORYBOARD_TASK_PROGRESS;
    const items = value.items && typeof value.items === 'object' ? value.items : {};
    const itemList = Object.values(items);
    if (itemList.length > 0) {
        const started = itemList.length;
        const completed = itemList.filter((item) => String(item?.status || '').toLowerCase() === 'completed').length;
        const failed = itemList.filter((item) => String(item?.status || '').toLowerCase() === 'failed').length;
        const running = itemList.filter((item) => (
            ['starting', 'generating', 'importing'].includes(String(item?.status || '').toLowerCase())
        )).length;
        const waiting = itemList.filter((item) => (
            String(item?.status || '').toLowerCase() === 'waiting_env'
        )).length;
        return { started, completed, failed, running, waiting, items };
    }
    return {
        started: Number(value.started || 0) || 0,
        completed: Number(value.completed || 0) || 0,
        failed: Number(value.failed || 0) || 0,
        running: Number(value.running || 0) || 0,
        items: {},
    };
};

const pickRicherStoryboardTaskProgress = (...candidates) => {
    let best = EMPTY_STORYBOARD_TASK_PROGRESS;
    let bestScore = -1;
    for (const candidate of candidates) {
        const normalized = normalizeStoryboardTaskProgress(candidate);
        const itemCount = Object.keys(normalized.items || {}).length;
        const score = (itemCount * 1000)
            + (Number(normalized.started || 0) * 10)
            + Number(normalized.completed || 0)
            + Number(normalized.failed || 0)
            + Number(normalized.running || 0);
        if (score > bestScore) {
            best = normalized;
            bestScore = score;
        }
    }
    return best;
};

const resolveLiveImportedSceneIdsToSkip = async ({
    fetchScenesFn,
    episodeId,
    liveImportedIds,
}) => {
    const stableEpisodeId = Number(episodeId || 0);
    if (!stableEpisodeId || typeof fetchScenesFn !== 'function') {
        return [];
    }
    const liveIds = (Array.isArray(liveImportedIds) ? liveImportedIds : [])
        .map((id) => String(id || '').trim())
        .filter(Boolean);
    if (!liveIds.length) return [];
    let dbScenes = [];
    try {
        dbScenes = await fetchScenesFn(stableEpisodeId);
    } catch (_) {
        return [];
    }
    return liveIds.filter((patchSceneId) => dbSceneMatchesPatchSceneId(dbScenes, patchSceneId));
};

const filterPatchMapToMissingScenes = (patchMap, dbScenes) => {
    const missing = {};
    Object.entries(patchMap || {}).forEach(([sceneId, entry]) => {
        const stableSceneId = String(sceneId || '').trim();
        if (!stableSceneId) return;
        if (!dbSceneMatchesPatchSceneId(dbScenes, stableSceneId)) {
            missing[stableSceneId] = entry;
        }
    });
    return missing;
};

const sceneUnitIdsMatch = (leftId, rightId, sceneOrder, episodePrefix) => (
    canonicalizeSceneUnitId(leftId, sceneOrder, episodePrefix)
    === canonicalizeSceneUnitId(rightId, sceneOrder, episodePrefix)
);

/** Align script-marker units with Stage 2 scene_markdown display (id / order / name). */
const alignSceneBeatsCandidatesWithStage2 = (scriptCandidates, stage2ByScene, episodePrefix) => {
    const units = Array.isArray(scriptCandidates) ? scriptCandidates : [];
    const byScene = stage2ByScene && typeof stage2ByScene === 'object' ? stage2ByScene : {};
    const stage2Entries = Object.entries(byScene)
        .map(([rawId, entry]) => {
            const sceneId = String(entry?.scene_id || rawId || '').trim();
            if (!sceneId) return null;
            const sceneOrder = Number(entry?.scene_order) || deriveSceneOrderFromSceneId(sceneId) || 0;
            const sceneName = String(entry?.scene_name || '').trim();
            return { sceneId, sceneOrder, sceneName };
        })
        .filter(Boolean)
        .sort((left, right) => {
            if ((left.sceneOrder || 0) !== (right.sceneOrder || 0)) {
                return (left.sceneOrder || 0) - (right.sceneOrder || 0);
            }
            return String(left.sceneId).localeCompare(String(right.sceneId));
        });

    if (!stage2Entries.length || !units.length) {
        return units;
    }

    const used = new Set();
    const takeMatch = (predicate) => {
        const index = units.findIndex((unit, idx) => !used.has(idx) && predicate(unit, idx));
        if (index < 0) return null;
        used.add(index);
        return units[index];
    };

    const aligned = stage2Entries.map((entry) => {
        let match = takeMatch((unit) => sceneUnitIdsMatch(
            unit?.sceneId,
            entry.sceneId,
            entry.sceneOrder || unit?.sceneOrder,
            episodePrefix
        ));
        if (!match && entry.sceneOrder > 0) {
            match = takeMatch((unit) => Number(unit?.sceneOrder) === Number(entry.sceneOrder));
        }
        const displayLabel = entry.sceneName
            ? `${entry.sceneId} · ${entry.sceneName}`
            : (match?.displayLabel || entry.sceneId);
        if (match) {
            return {
                ...match,
                sceneId: entry.sceneId,
                sceneOrder: entry.sceneOrder || match.sceneOrder,
                displayLabel,
                stage2Aligned: true,
            };
        }
        return {
            sceneId: entry.sceneId,
            sceneOrder: entry.sceneOrder || 0,
            sceneText: '',
            displayLabel,
            markerStartToken: `[SCENE_START:${entry.sceneId}]`,
            markerEndToken: `[SCENE_END:${entry.sceneId}]`,
            stage2Aligned: true,
            unmatchedScriptUnit: true,
        };
    });

    // Keep Stage 1 units missing from Stage 2 so incomplete orchestration remains recoverable.
    units.forEach((unit, idx) => {
        if (used.has(idx)) return;
        aligned.push({
            ...unit,
            stage2Aligned: false,
            missingFromStage2: true,
            displayLabel: unit?.displayLabel || unit?.sceneId,
        });
    });

    return aligned.sort((left, right) => {
        if ((left.sceneOrder || 0) !== (right.sceneOrder || 0)) {
            return (left.sceneOrder || 0) - (right.sceneOrder || 0);
        }
        return String(left.sceneId || '').localeCompare(String(right.sceneId || ''));
    });
};

const collectOrchestrationResetSceneIds = (units, episodePrefix) => {
    const ids = new Set();
    (Array.isArray(units) ? units : []).forEach((unit, idx) => {
        const order = Number(unit?.sceneOrder) || idx + 1;
        const raw = String(unit?.sceneId || '').trim();
        const canonical = canonicalizeSceneUnitId(raw, order, episodePrefix);
        if (canonical) ids.add(canonical);
        if (/^\d+$/.test(raw)) ids.add(raw);
        const canonicalMatch = canonical.match(/^EP\d+_SC(\d+)$/i);
        if (canonicalMatch) ids.add(String(Number(canonicalMatch[1])));
    });
    return [...ids].filter(Boolean);
};

const SCENES_BLOCK_START_TOKEN = '[SCENES_BLOCK_START]';
const SCENES_BLOCK_END_TOKEN = '[SCENES_BLOCK_END]';
const ENTITY_PROFILE_START_TOKEN = '[ENTITY_PROFILE_START]';
const ENTITY_PROFILE_END_TOKEN = '[ENTITY_PROFILE_END]';
const BLOCK_MARKER_LINE_PATTERN = /^\s*`?\[(?:SCENES?_BLOCK_(?:START|END))\]`?\s*$/gim;
const SCENE_MARKER_LINE_PATTERN = /^\s*`?\[SCENE_(?:START|END)(?::[^\]]+)?\]`?\s*$/gim;
const MIN_SCENE_UNIT_BODY_CHARS = 50;

/**
 * Extract Part 2【角色设定】block (`[ENTITY_PROFILE_START]…[ENTITY_PROFILE_END]`)
 * from Stage 1 adapted script. Falls back to bare 【角色设定】… before first SCENE_START.
 */
const extractEntityProfileBlockFromAdapted = (adaptedScript) => {
    const text = String(adaptedScript || '');
    if (!text.trim()) return '';

    const startRe = /`?\[ENTITY_PROFILE_START(?::([^\s\]]+))?\]`?/i;
    const endRe = /`?\[ENTITY_PROFILE_END(?::([^\s\]]+))?\]`?/i;
    const startMatch = startRe.exec(text);
    if (startMatch) {
        const afterStart = text.slice(startMatch.index);
        const endMatch = endRe.exec(afterStart);
        if (endMatch) {
            return afterStart.slice(0, endMatch.index + endMatch[0].length).trim();
        }
        const sceneMatch = /`?\[SCENE_START(?::([^\s\]]+))?\]`?/i.exec(afterStart);
        let body = (sceneMatch ? afterStart.slice(0, sceneMatch.index) : afterStart).replace(/\s+$/, '');
        if (body && !endRe.test(body)) {
            body = `${body}\n${ENTITY_PROFILE_END_TOKEN}`;
        }
        return body.trim();
    }

    const headerIdx = text.search(/【角色设定】/);
    if (headerIdx < 0) return '';
    const firstScene = /`?\[SCENE_START(?::([^\s\]]+))?\]`?/i.exec(text);
    if (firstScene && headerIdx >= firstScene.index) return '';
    const end = firstScene ? firstScene.index : text.length;
    const body = text.slice(headerIdx, end).trim();
    if (!body) return '';
    return `${ENTITY_PROFILE_START_TOKEN}\n${body}\n${ENTITY_PROFILE_END_TOKEN}`;
};

const stripBlockLevelMarkersFromSceneText = (text) => (
    String(text || '')
        .replace(BLOCK_MARKER_LINE_PATTERN, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim()
);

const normalizeSceneUnitBodyForMeasure = (text) => (
    stripBlockLevelMarkersFromSceneText(text)
        .replace(SCENE_MARKER_LINE_PATTERN, '')
        .replace(/\s+/g, ' ')
        .trim()
);

const sceneUnitBodyCharCount = (text) => normalizeSceneUnitBodyForMeasure(text).length;

const isViableSceneUnitBody = (text, minChars = MIN_SCENE_UNIT_BODY_CHARS) => (
    sceneUnitBodyCharCount(text) >= Math.max(1, Number(minChars) || MIN_SCENE_UNIT_BODY_CHARS)
);

const normalizeSceneMarkerScriptText = (scriptText) => {
    const text = String(scriptText || '').replace(/\r\n/g, '\n');
    if (!text.trim()) return '';
    return text.replace(
        /`+(\[(?:SCENES?_BLOCK_(?:START|END)|SCENE_(?:START|END)(?::[^\]]+)?)])`+/gi,
        '$1'
    );
};

const resolveSceneBlockText = (scriptText) => {
    const normalized = normalizeSceneMarkerScriptText(scriptText);
    if (!normalized.trim()) return '';
    const startMatch = /`?\[SCENES_BLOCK_START\]`?/i.exec(normalized);
    if (!startMatch) return normalized.trim();
    const afterStart = normalized.slice(startMatch.index + startMatch[0].length);
    const endMatches = [...afterStart.matchAll(/`?\[SCENES_BLOCK_END\]`?/gi)];
    const blockText = (endMatches.length > 0
        ? afterStart.slice(0, endMatches[endMatches.length - 1].index)
        : afterStart).trim();
    return blockText || normalized.trim();
};

const inferSceneIdFromBareStartContext = (blockText, markerEndPos) => {
    const after = String(blockText || '').slice(Math.max(0, Number(markerEndPos) || 0), Math.max(0, Number(markerEndPos) || 0) + 120);
    const firstLine = after.split('\n')[0] || after;
    const patterns = [
        /^\s*(EP\d+_SC\d+[A-Za-z]?)\b/i,
        /^\s*Scene\s*(\d+)\b/i,
        /^\s*【场景\s*(\d+)/,
        /^\s*场景\s*(\d+)\s*[：:\-—–]/,
        /^\s*(\d+)\s*[—–:\-【]/,
    ];
    for (const pattern of patterns) {
        const match = firstLine.match(pattern);
        if (!match) continue;
        const value = String(match[1] || '').trim();
        if (value) return value;
    }
    return '';
};

const collectSceneBoundaryMarkers = (blockText) => {
    const markers = [];
    // Accept both [SCENE_START:ID] and bare [SCENE_START] (Stage 1 template historically used bare form).
    // Also recover IDs from title lines like: [SCENE_START] Scene 4 — Winery Courtyard...
    const startPattern = /`?\[SCENE_START(?::([^\s\]]+))?\]`?/gi;
    const endPattern = /`?\[SCENE_END(?::([^\s\]]+))?\]`?/gi;
    let match;
    while ((match = startPattern.exec(blockText)) !== null) {
        const explicitId = String(match[1] || '').trim();
        const inferredId = explicitId || inferSceneIdFromBareStartContext(blockText, match.index + match[0].length);
        markers.push({
            pos: match.index,
            endPos: match.index + match[0].length,
            kind: 'start',
            sceneId: inferredId,
        });
    }
    while ((match = endPattern.exec(blockText)) !== null) {
        markers.push({
            pos: match.index,
            endPos: match.index + match[0].length,
            kind: 'end',
            sceneId: String(match[1] || '').trim(),
        });
    }
    markers.sort((a, b) => (a.pos - b.pos) || (a.kind === 'end' ? -1 : 1));

    let autoIndex = 0;
    let lastStartId = '';
    return markers.map((marker) => {
        if (marker.kind === 'start') {
            let sceneId = marker.sceneId;
            if (!sceneId) {
                autoIndex += 1;
                sceneId = String(autoIndex);
            } else {
                const numericId = Number(sceneId);
                if (Number.isFinite(numericId) && numericId > autoIndex) {
                    autoIndex = numericId;
                }
            }
            lastStartId = sceneId;
            return { ...marker, sceneId };
        }
        const sceneId = marker.sceneId || lastStartId || String(Math.max(autoIndex, 1));
        return { ...marker, sceneId };
    });
};

const decrementCanonicalSceneId = (sceneId) => {
    const match = String(sceneId || '').trim().match(/^(EP\d+)_SC(\d+)$/i);
    if (!match) return '';
    const order = Number(match[2]);
    if (!Number.isFinite(order) || order <= 1) return '';
    return `${String(match[1]).toUpperCase()}_SC${String(order - 1).padStart(2, '0')}`;
};

const incrementCanonicalSceneId = (sceneId) => {
    const match = String(sceneId || '').trim().match(/^(EP\d+)_SC(\d+)$/i);
    if (!match) return '';
    return `${String(match[1]).toUpperCase()}_SC${String(Number(match[2]) + 1).padStart(2, '0')}`;
};

const inferPreludeSceneId = (startMarker, segmentCount) => (
    decrementCanonicalSceneId(startMarker?.sceneId) || String(segmentCount + 1)
);

const inferTrailingSceneId = (activeStartId, segments, markers) => {
    if (activeStartId) return activeStartId;
    const lastMarker = markers[markers.length - 1];
    if (lastMarker?.kind === 'end') {
        const incremented = incrementCanonicalSceneId(lastMarker.sceneId);
        if (incremented) return incremented;
    }
    if (segments.length > 0) {
        const incremented = incrementCanonicalSceneId(segments[segments.length - 1][0]);
        if (incremented) return incremented;
    }
    return String(segments.length + 1);
};

const dedupeSegmentSceneIds = (segments) => {
    const seen = new Set();
    const deduped = [];
    segments.forEach(([sceneId, sceneText], idx) => {
        const body = String(sceneText || '').trim();
        if (!body || !isViableSceneUnitBody(body)) return;
        let resolvedId = String(sceneId || '').trim() || String(idx + 1);
        if (seen.has(resolvedId)) resolvedId = String(idx + 1);
        seen.add(resolvedId);
        deduped.push([resolvedId, body]);
    });
    return deduped;
};

const segmentScenesByBoundaryMarkers = (blockText) => {
    const markers = collectSceneBoundaryMarkers(blockText);
    if (!markers.length) {
        const body = String(blockText || '').trim();
        return body && isViableSceneUnitBody(body) ? [['1', body]] : [];
    }

    const segments = [];
    let contentCursor = 0;
    let activeStartId = '';
    let pendingLeading = '';

    markers.forEach((marker) => {
        const chunk = stripBlockLevelMarkersFromSceneText(blockText.slice(contentCursor, marker.pos));
        if (marker.kind === 'end') {
            let body = chunk;
            if (pendingLeading) {
                body = body ? `${pendingLeading}\n\n${body}`.trim() : pendingLeading;
                pendingLeading = '';
            }
            if (body) segments.push([marker.sceneId, body]);
            activeStartId = '';
        } else {
            if (chunk) {
                if (activeStartId) {
                    segments.push([activeStartId, chunk]);
                } else {
                    pendingLeading = chunk;
                }
            }
            activeStartId = marker.sceneId;
        }
        contentCursor = marker.endPos;
    });

    const trailing = stripBlockLevelMarkersFromSceneText(blockText.slice(contentCursor));
    if (trailing) {
        let trailBody = trailing;
        if (pendingLeading) {
            trailBody = `${pendingLeading}\n\n${trailBody}`.trim();
            pendingLeading = '';
        }
        segments.push([inferTrailingSceneId(activeStartId, segments, markers), trailBody]);
    } else if (pendingLeading) {
        if (activeStartId) {
            segments.push([activeStartId, pendingLeading]);
        } else if (segments.length > 0) {
            const last = segments[segments.length - 1];
            segments[segments.length - 1] = [last[0], `${last[1]}\n\n${pendingLeading}`.trim()];
        } else {
            segments.push([inferPreludeSceneId(markers[0], segments.length), pendingLeading]);
        }
    }
    return segments;
};

const buildSingleSceneUnitFromText = (scriptText) => {
    const normalized = normalizeSceneMarkerScriptText(scriptText);
    const body = resolveSceneBlockText(normalized).trim() || normalized.trim();
    if (!body || !isViableSceneUnitBody(body)) return null;
    return {
        sceneId: '1',
        sceneOrder: 1,
        sceneText: body,
        markerStartToken: '[SCENE_START:1]',
        markerEndToken: '[SCENE_END:1]',
    };
};

const parseSceneUnitsFromScriptMarkersText = (scriptText) => {
    const normalized = normalizeSceneMarkerScriptText(scriptText);
    if (!normalized.trim()) return [];

    const blockText = resolveSceneBlockText(normalized);
    if (!blockText.trim()) {
        const fallbackUnit = buildSingleSceneUnitFromText(normalized);
        return fallbackUnit ? [fallbackUnit] : [];
    }

    const segments = dedupeSegmentSceneIds(segmentScenesByBoundaryMarkers(blockText));
    if (!segments.length) {
        const fallbackUnit = buildSingleSceneUnitFromText(normalized);
        return fallbackUnit ? [fallbackUnit] : [];
    }

    return segments.map(([sceneId, sceneText], idx) => ({
        sceneId,
        sceneOrder: idx + 1,
        sceneText,
        markerStartToken: `[SCENE_START:${sceneId}]`,
        markerEndToken: `[SCENE_END:${sceneId}]`,
    }));
};

/** Extract legacy `- Beat N` sections and wrap with BEAT_START/END. */
const extractLegacyBeatSectionsFromSceneText = (sceneText) => {
    const text = String(sceneText || '');
    const beatLineRe = /^\s*-\s*Beat\s+(\d+)\b/gm;
    const matches = [];
    let match;
    while ((match = beatLineRe.exec(text)) !== null) {
        matches.push({ index: match.index, beatN: String(match[1] || '').trim() });
    }
    if (!matches.length) return '';
    return matches.map((item, idx) => {
        const beatN = item.beatN || String(idx + 1);
        const start = item.index;
        const end = idx + 1 < matches.length ? matches[idx + 1].index : text.length;
        const body = text.slice(start, end).trim();
        if (!body) return '';
        return `[BEAT_START:${beatN}]\n${body}\n[BEAT_END:${beatN}]`;
    }).filter(Boolean).join('\n\n').trim();
};

/** Stage 2.2 input: only `[BEAT_START:…]`…`[BEAT_END:…]` blocks from a scene body. */
const extractBeatBlocksFromSceneText = (sceneText) => {
    const text = String(sceneText || '');
    if (!text.trim()) return '';
    const startRe = /`?\[BEAT_START(?::([^\s\]]+))?\]`?/gi;
    const starts = [];
    let match;
    while ((match = startRe.exec(text)) !== null) {
        starts.push({
            index: match.index,
            endPos: match.index + match[0].length,
            beatId: String(match[1] || '').trim(),
        });
    }
    if (!starts.length) {
        return extractLegacyBeatSectionsFromSceneText(text);
    }
    const endRe = /`?\[BEAT_END(?::([^\s\]]+))?\]`?/gi;
    return starts.map((startItem, idx) => {
        const beatId = startItem.beatId || String(idx + 1);
        const nextStart = idx + 1 < starts.length ? starts[idx + 1].index : text.length;
        endRe.lastIndex = startItem.endPos;
        const endMatch = endRe.exec(text);
        let block;
        if (endMatch && endMatch.index <= nextStart) {
            block = text.slice(startItem.index, endMatch.index + endMatch[0].length).trim();
        } else {
            block = text.slice(startItem.index, nextStart).replace(/\s+$/, '');
            if (block && !/`?\[BEAT_END(?::[^\]]+)?\]`?/i.test(block)) {
                block = `${block}\n[BEAT_END:${beatId}]`;
            }
        }
        return String(block || '').trim();
    }).filter(Boolean).join('\n\n').trim();
};

const MIN_SCENE_BEATS_CHARS = 20;

/** Literal "Beat 1" or structured [BEAT_START:1] — required for Stage 2.2 orchestration input. */
const sceneTextHasBeat1 = (text) => (
    /(?:\[\s*BEAT_START\s*:\s*1\s*\])|(?:\bBeat\s+1\b)/i.test(String(text || ''))
);

/** Strip BEAT_START/END markers so length reflects Beat body content. */
const stripBeatBoundaryMarkers = (beatsText) => String(beatsText || '')
    .replace(/`?\[BEAT_START(?::[^\]]+)?\]`?/gi, '')
    .replace(/`?\[BEAT_END(?::[^\]]+)?\]`?/gi, '')
    .trim();

/**
 * Resolve Stage 2.2 Beat body: prefer BEAT_START/END extraction;
 * on split failure / too-short Beats, fall back to the entire scene text.
 * Returns `{ bodyText, usedSceneFallback }`. Throws only if final body is still too short.
 */
const resolveSceneBeatsBodyForStage22 = (sceneText, sceneId = '') => {
    const source = String(sceneText || '').trim();
    const id = String(sceneId || 'unknown').trim() || 'unknown';
    if (!sceneTextHasBeat1(source)) {
        throw new Error(`SCENE_MARKDOWN_MISSING_BEAT_1:${id}`);
    }
    const beatsOnly = extractBeatBlocksFromSceneText(source).trim();
    const extractedChars = stripBeatBoundaryMarkers(beatsOnly).length;
    if (beatsOnly && extractedChars >= MIN_SCENE_BEATS_CHARS) {
        return { bodyText: beatsOnly, usedSceneFallback: false };
    }
    if (source.length >= MIN_SCENE_BEATS_CHARS) {
        return { bodyText: source, usedSceneFallback: true, extractedChars };
    }
    const finalChars = Math.max(extractedChars, source.length);
    throw new Error(
        `SCENE_MARKDOWN_BEATS_TOO_SHORT:${id}:beats_chars=${finalChars}<${MIN_SCENE_BEATS_CHARS}`
    );
};

/** @deprecated prefer resolveSceneBeatsBodyForStage22; kept as thin wrapper. */
const assertSceneBeatsMinLength = (sceneText, sceneId = '') => (
    resolveSceneBeatsBodyForStage22(sceneText, sceneId).bodyText
);

/** Legacy 【主环境】…【未落环境实体清单】…【衍生环境】 when ENV_BLOCK markers are absent. */
const extractLegacyEnvBlockFromSceneText = (sceneText) => {
    const text = String(sceneText || '');
    const mainIdx = text.search(/【主环境】/);
    if (mainIdx < 0) return '';
    const endRe = /\[BEAT_START|\[SCENE_END|【Scene实体覆盖】|【观察视角与空间建置】|【场景切换|【对白拆句/i;
    const rest = text.slice(mainIdx);
    const endMatch = endRe.exec(rest);
    const body = (endMatch ? rest.slice(0, endMatch.index) : rest).trim();
    if (!body) return '';
    return `[ENV_BLOCK_START]\n${body}\n[ENV_BLOCK_END]`;
};

/** Extract `[ENV_BLOCK_START]…[ENV_BLOCK_END]` (主环境+未落环境实体清单+衍生环境). */
const extractEnvBlockFromSceneText = (sceneText) => {
    const text = String(sceneText || '');
    if (!text.trim()) return '';
    const startRe = /`?\[ENV_BLOCK_START(?::([^\s\]]+))?\]`?/gi;
    const starts = [];
    let match;
    while ((match = startRe.exec(text)) !== null) {
        starts.push({ index: match.index, endPos: match.index + match[0].length });
    }
    if (!starts.length) {
        return extractLegacyEnvBlockFromSceneText(text);
    }
    const endRe = /`?\[ENV_BLOCK_END(?::([^\s\]]+))?\]`?/gi;
    return starts.map((startItem, idx) => {
        const nextStart = idx + 1 < starts.length ? starts[idx + 1].index : text.length;
        endRe.lastIndex = startItem.endPos;
        const endMatch = endRe.exec(text);
        let block;
        if (endMatch && endMatch.index <= nextStart) {
            block = text.slice(startItem.index, endMatch.index + endMatch[0].length).trim();
        } else {
            block = text.slice(startItem.index, nextStart).replace(/\s+$/, '');
            if (block && !/`?\[ENV_BLOCK_END(?::[^\]]+)?\]`?/i.test(block)) {
                block = `${block}\n[ENV_BLOCK_END]`;
            }
        }
        return String(block || '').trim();
    }).filter(Boolean).join('\n\n').trim();
};

/** Per-scene Stage 2.1 body: ENV_BLOCK + Beats (fallback to full scene). */
const extractSceneEnvAndBeatsBody = (sceneText, sceneId = '') => {
    const source = stripBlockLevelMarkersFromSceneText(sceneText).trim();
    if (!source) return { bodyText: '', source: 'scene_fallback' };
    const envBlock = extractEnvBlockFromSceneText(source).trim();
    const beatsOnly = extractBeatBlocksFromSceneText(source).trim();
    const beatsChars = stripBeatBoundaryMarkers(beatsOnly).length;
    const chunks = [];
    if (envBlock) chunks.push(envBlock);
    if (beatsOnly && beatsChars >= MIN_SCENE_BEATS_CHARS) chunks.push(beatsOnly);
    if (chunks.length) {
        return { bodyText: chunks.join('\n\n').trim(), source: 'extracted' };
    }
    return { bodyText: source, source: 'scene_fallback', sceneId };
};

/**
 * Rebuild Stage 2.1 script: optional【角色设定】+ per-scene ENV_BLOCK + Beats
 * (replaces full Stage 1 adapted script).
 */
const buildAssetsExtractionScriptFromAdapted = (adaptedScript) => {
    const script = String(adaptedScript || '').trim();
    if (!script) return '';
    const entityProfile = extractEntityProfileBlockFromAdapted(script);
    let units = [];
    try {
        units = parseSceneUnitsFromScriptMarkersText(script);
    } catch (_) {
        return script;
    }
    if (!units.length) return script;
    const parts = [];
    if (entityProfile) parts.push(entityProfile);
    parts.push(SCENES_BLOCK_START_TOKEN);
    let fallbackCount = 0;
    units.forEach((unit) => {
        const sceneId = String(unit?.sceneId || '').trim();
        let markerStart = String(unit?.markerStartToken || '').trim();
        let markerEnd = String(unit?.markerEndToken || '').trim();
        if (!markerStart && sceneId) markerStart = `[SCENE_START:${sceneId}]`;
        if (!markerEnd && sceneId) markerEnd = `[SCENE_END:${sceneId}]`;
        const resolved = extractSceneEnvAndBeatsBody(unit?.sceneText || '', sceneId);
        if (resolved.source === 'scene_fallback') fallbackCount += 1;
        if (markerStart) parts.push(markerStart);
        if (resolved.bodyText) parts.push(resolved.bodyText);
        if (markerEnd) parts.push(markerEnd);
    });
    parts.push(SCENES_BLOCK_END_TOKEN);
    const rebuilt = parts.filter((p) => String(p || '').trim()).join('\n').trim();
    if (fallbackCount > 0) {
        // Caller may log; keep helper free of UI deps.
    }
    return rebuilt || script;
};

const createSceneOrchestrationProgressPoller = ({
    getSnapshot,
    episodeId,
    sceneUnits,
    onPhase,
    onSceneReady,
    episodePrefix = 'EP01',
    intervalMs = 1000,
}) => {
    const reportedByScene = new Map();
    const readyScenes = new Set();
    let stopped = false;
    const totalScenes = Array.isArray(sceneUnits) ? sceneUnits.length : 0;

    const trySceneReady = async (sceneId, row, unitHint) => {
        const stableSceneId = String(sceneId || '').trim();
        if (!stableSceneId || readyScenes.has(stableSceneId)) return;
        const sceneMarkdown = String(row?.scene_markdown || '').trim();
        if (!sceneMarkdown) return;
        const phase = deriveSceneOrchestrationPhase(row);
        if (phase !== 'llm_returned' && phase !== 'importing' && phase !== 'imported') return;
        readyScenes.add(stableSceneId);
        try {
            await onSceneReady?.({
                sceneId: stableSceneId,
                sceneOrder: row?.scene_order ?? unitHint?.sceneOrder,
                totalScenes,
                markdown: sceneMarkdown,
                phase,
            });
        } catch (_) {
            readyScenes.delete(stableSceneId);
        }
    };

    const pollOnce = async () => {
        if (stopped || !episodeId) return;
        try {
            const snapshot = await getSnapshot(episodeId);
            const rows = Array.isArray(snapshot?.scene_units) ? snapshot.scene_units : [];
            const byId = Object.fromEntries(
                rows.map((row) => [String(row.scene_id || '').trim(), row]).filter(([sceneId]) => sceneId)
            );
            for (const unit of sceneUnits || []) {
                const sceneId = String(unit?.sceneId || unit?.scene_id || '').trim();
                if (!sceneId) continue;
                let row = byId[sceneId];
                if (!row) {
                    row = rows.find((candidate) => sceneUnitIdsMatch(
                        candidate?.scene_id,
                        sceneId,
                        unit?.sceneOrder ?? candidate?.scene_order,
                        episodePrefix
                    ));
                }
                if (!row) continue;
                const phase = deriveSceneOrchestrationPhase(row);
                const reported = reportedByScene.get(sceneId) || new Set();
                if (!reported.has(phase)) {
                    reported.add(phase);
                    reportedByScene.set(sceneId, reported);
                    onPhase({
                        sceneId,
                        phase,
                        sceneOrder: row.scene_order ?? unit?.sceneOrder,
                        totalScenes,
                        errorCode: row.parse_error_code,
                    });
                }
                await trySceneReady(sceneId, row, unit);
            }
            for (const row of rows) {
                const sceneId = String(row?.scene_id || '').trim();
                if (!sceneId) continue;
                await trySceneReady(sceneId, row, byId[sceneId] ? null : row);
            }
        } catch (_) {
            // polling is best-effort
        }
    };

    const timer = setInterval(pollOnce, intervalMs);
    pollOnce();
    return () => {
        stopped = true;
        clearInterval(timer);
    };
};

/** Max automatic fallback reruns for scene beats / asset generation (excluding the initial run). */
const MAX_ANALYSIS_FALLBACK_ATTEMPTS = 2;


const TERMINAL_ASYNC_TASK_STATUSES = new Set([
    'completed', 'success', 'succeeded', 'done', 'finished',
    'failed', 'error', 'timeout', 'canceled', 'cancelled', 'stopped',
]);

const peekAsyncTaskTerminalStatus = async (taskId) => {
    const id = String(taskId || '').trim();
    if (!id) return null;
    try {
        const res = await api.get(`/tasks/${id}`, { params: { _ts: Date.now() }, timeout: 15000 });
        const status = String(res?.data?.status || '').trim().toLowerCase();
        return TERMINAL_ASYNC_TASK_STATUSES.has(status) ? status : null;
    } catch (error) {
        const status = Number(error?.response?.status || 0);
        const detail = String(error?.response?.data?.detail || error?.message || '').trim().toLowerCase();
        if (status === 404 || detail.includes('task not found') || detail.includes('not found')) {
            return 'not_found';
        }
        return null;
    }
};

const isEpisodeAnalysisTaskLive = (episodeId, {
    loadAnalysisTaskMarker,
    isAnalyzing = false,
    isRetryingPhase2 = false,
    analysisRunInFlight = false,
    analysisResumeInFlight = false,
    phase2GenerationInFlight = false,
} = {}) => {
    const id = Number(episodeId || 0);
    if (!id) return false;

    if (isAnalyzing || isRetryingPhase2) return true;
    if (analysisRunInFlight || analysisResumeInFlight || phase2GenerationInFlight) return true;

    const marker = typeof loadAnalysisTaskMarker === 'function' ? loadAnalysisTaskMarker(id) : null;
    const markerTaskId = String(marker?.taskId || '').trim();
    if (markerTaskId && isAsyncTaskPollInFlight(markerTaskId)) return true;

    const activeRun = getEpisodeAnalysisRun(id);
    const runTaskId = String(activeRun?.taskId || markerTaskId || '').trim();
    if (activeRun?.promise && runTaskId && isAsyncTaskPollInFlight(runTaskId)) return true;

    return false;
};

const firstPositiveFiniteNumber = (...values) => {
    for (const value of values) {
        const numberValue = Number(value);
        if (Number.isFinite(numberValue) && numberValue > 0) return numberValue;
    }
    return 0;
};

const resolveCompletenessStatus = (analysisCount, importedCount) => {
    const expected = Number(analysisCount || 0);
    const actual = Number(importedCount || 0);
    if (expected <= 0 && actual <= 0) return 'none';
    if (expected <= 0 && actual > 0) return 'extra';
    if (actual >= expected) return 'ok';
    if (actual > 0) return 'partial';
    return 'missing';
};

const syncScenePostImportCheckedCount = (importReport, postImportSceneSubjectReport) => {
    const importedRows = Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows.length : 0;
    const importStatsTotal = Number(importReport?.importStats?.scenesCreated || 0) + Number(importReport?.importStats?.scenesUpdated || 0);
    const resolvedCheckedSceneCount = firstPositiveFiniteNumber(
        importedRows,
        importStatsTotal,
        importReport?.dbPersistedCounts?.scenes?.currentEpisode,
        postImportSceneSubjectReport?.checkedSceneCount,
    );
    if (!postImportSceneSubjectReport || typeof postImportSceneSubjectReport !== 'object') {
        return resolvedCheckedSceneCount > 0 ? { checkedSceneCount: resolvedCheckedSceneCount } : postImportSceneSubjectReport;
    }
    return {
        ...postImportSceneSubjectReport,
        checkedSceneCount: resolvedCheckedSceneCount,
    };
};

const resolveImportReportSceneCount = (importReport, scenePostReport, dbSceneCount = null) => firstPositiveFiniteNumber(
    dbSceneCount,
    importReport?.dbPersistedCounts?.scenes?.currentEpisode,
    Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows.length : null,
    (Number(importReport?.importStats?.scenesCreated || 0) + Number(importReport?.importStats?.scenesUpdated || 0)) || null,
    importReport?.importStats?.scenesCreated,
    importReport?.dbRunInsertedCounts?.scenes?.created,
    scenePostReport?.checkedSceneCount,
);

const normalizeAssetReportType = (value) => {
    const key = String(value || '').trim().toLowerCase();
    if (['character', 'characters', 'role', 'roles', '人物', '角色'].includes(key)) return 'character';
    if (['prop', 'props', 'item', 'items', '道具', '物件'].includes(key)) return 'prop';
    if (['environment', 'environments', 'env', 'scene', 'scenes', '空镜', '场景', '环境'].includes(key)) return 'environment';
    if (['poster', 'posters', 'cover', 'covers', 'cover_poster', '海报', '封面'].includes(key)) return 'poster';
    return key;
};

const toPositiveCount = (value) => {
    const count = Number(value);
    return Number.isFinite(count) && count > 0 ? count : 0;
};

const countAssetItemsByType = (items, type) => {
    if (!Array.isArray(items)) return 0;
    return items.reduce((count, item) => (
        count + (normalizeAssetReportType(item?.type || item?.entity_type || item?.subject_type) === type ? 1 : 0)
    ), 0);
};

const resolveImportReportAssetInsertedCount = (importReport, type) => {
    const scenePostReport = importReport?.sceneSubjectPostImportReport || {};
    const supplementReport = scenePostReport?.supplementReport || {};
    return Math.max(
        toPositiveCount(importReport?.dbRunInsertedCounts?.entities?.[type]),
        toPositiveCount(importReport?.importedSubjectCounts?.[type]),
        toPositiveCount(scenePostReport?.importedSubjectCounts?.[type]),
        toPositiveCount(supplementReport?.countsByType?.[type]),
        countAssetItemsByType(importReport?.createdSubjectItems, type),
        countAssetItemsByType(supplementReport?.createdItems, type),
    );
};

const resolveImportReportAssetSkippedCount = (importReport, type) => {
    const scenePostReport = importReport?.sceneSubjectPostImportReport || {};
    const supplementReport = scenePostReport?.supplementReport || {};
    return Math.max(
        countAssetItemsByType(importReport?.skippedSubjectItems, type),
        countAssetItemsByType(supplementReport?.skippedItems, type),
    );
};

const ASSET_CATEGORY_SUBTASK_KEYS = {
    characters: ['characters', 'character'],
    props: ['props', 'prop'],
    environments: ['environments', 'environment'],
    posters: ['posters', 'poster', 'covers', 'cover', 'environments', 'environment'],
};

const isAssetCategorySatisfiedBySubtaskReports = (subtaskReports, categoryKey) => {
    const aliases = ASSET_CATEGORY_SUBTASK_KEYS[String(categoryKey || '').trim()] || [String(categoryKey || '').trim().toLowerCase()];
    if (!Array.isArray(subtaskReports) || subtaskReports.length === 0) return false;
    return subtaskReports.some((report) => {
        const reportKey = String(report?.key || '').trim().toLowerCase();
        if (!aliases.includes(reportKey)) return false;
        const status = String(report?.status || '').trim().toLowerCase();
        if (status !== 'ok') return false;
        return Number(report?.created || 0) + Number(report?.skipped || 0) > 0;
    });
};

const resolveSubtaskImportHandledCount = (scenePostReport, categoryKey = '') => {
    const subtaskReports = Array.isArray(scenePostReport?.subtaskReports) ? scenePostReport.subtaskReports : [];
    const aliases = ASSET_CATEGORY_SUBTASK_KEYS[String(categoryKey || '').trim()] || [String(categoryKey || '').trim().toLowerCase()];
    return subtaskReports.reduce((sum, report) => {
        const reportKey = String(report?.key || '').trim().toLowerCase();
        if (!aliases.includes(reportKey)) return sum;
        return sum + toPositiveCount(report?.created) + toPositiveCount(report?.skipped);
    }, 0);
};

const resolveImportReportAssetHandledCount = (importReport, type, categoryKey = '') => {
    const scenePostReport = importReport?.sceneSubjectPostImportReport || {};
    const supplementReport = scenePostReport?.supplementReport || {};
    const inserted = resolveImportReportAssetInsertedCount(importReport, type);
    const skipped = resolveImportReportAssetSkippedCount(importReport, type);
    const subtaskHandled = categoryKey ? resolveSubtaskImportHandledCount(scenePostReport, categoryKey) : 0;
    const supplementHandled = countAssetItemsByType(supplementReport?.createdItems, type)
        + countAssetItemsByType(supplementReport?.skippedItems, type);
    return Math.max(
        inserted,
        skipped,
        inserted + skipped,
        subtaskHandled,
        supplementHandled,
        toPositiveCount(importReport?.dbPersistedCounts?.entities?.[type]),
        toPositiveCount(scenePostReport?.importedSubjectCounts?.[type]),
    );
};

const resolveWorkflowImportReport = (analysisUiReport, episodeId) => {
    if (analysisUiReport?.importReport && typeof analysisUiReport.importReport === 'object') {
        return analysisUiReport.importReport;
    }
    const snapshot = loadAnalysisSessionSnapshot(episodeId);
    const persistedReport = snapshot?.progressUi?.uiReport?.importReport;
    if (persistedReport && typeof persistedReport === 'object') {
        return persistedReport;
    }
    return {};
};

const collectEntityPayloadNameCandidates = (item = {}) => {
    const names = [
        item?.subject_name_exact,
        item?.subject_name_zh,
        item?.subject_name,
        item?.name,
        item?.name_zh,
        item?.name_en,
    ]
        .map((value) => String(value || '').trim())
        .filter(Boolean);
    return Array.from(new Set(names));
};

const countEntityPayloadItemsCoveredInDb = (items, entityType, dbEntities) => {
    if (!Array.isArray(items) || items.length === 0) return 0;
    const normalizedType = normalizeAssetReportType(entityType);
    const entities = (Array.isArray(dbEntities) ? dbEntities : []).filter(
        (entity) => normalizeAssetReportType(entity?.type) === normalizedType
    );
    if (entities.length === 0) return 0;
    return items.reduce((count, item) => {
        const names = collectEntityPayloadNameCandidates(item);
        if (!names.length) return count;
        const matched = entities.some((entity) => (
            names.some((name) => entityTokenMatchesName(entity, name))
        ));
        return count + (matched ? 1 : 0);
    }, 0);
};

const countDbEntitiesByType = (entityType, dbEntities) => {
    const normalizedType = normalizeAssetReportType(entityType);
    return (Array.isArray(dbEntities) ? dbEntities : []).filter(
        (entity) => normalizeAssetReportType(entity?.type) === normalizedType,
    ).length;
};

const countSubjectIndexEntriesCoveredInDb = (entries, entityType, dbEntities) => {
    if (!Array.isArray(entries) || entries.length === 0) return 0;
    const normalizedType = normalizeAssetReportType(entityType);
    const entities = (Array.isArray(dbEntities) ? dbEntities : []).filter(
        (entity) => normalizeAssetReportType(entity?.type) === normalizedType
    );
    if (entities.length === 0) return 0;
    return entries.reduce((count, entry) => {
        const rawName = String(entry?.name || '').trim();
        if (!rawName) return count;
        const nameCandidates = rawName
            .split(/\s*\/\s*/)
            .map((part) => String(part || '').trim())
            .filter(Boolean);
        if (!nameCandidates.includes(rawName)) nameCandidates.unshift(rawName);
        const matched = entities.some((entity) => (
            nameCandidates.some((candidate) => entityTokenMatchesName(entity, candidate))
            || entityTokenMatchesName(entity, rawName)
        ));
        return count + (matched ? 1 : 0);
    }, 0);
};

const buildCompletedAnalysisUiReport = (payload = {}) => {
    const importReport = (payload?.importReport && typeof payload.importReport === 'object')
        ? payload.importReport
        : null;
    const scenePostReport = importReport?.sceneSubjectPostImportReport;
    const resolvedSceneImportCount = importReport
        ? resolveImportReportSceneCount(importReport, scenePostReport, null)
        : 0;
    const subtaskReports = Array.isArray(scenePostReport?.subtaskReports) ? scenePostReport.subtaskReports : [];
    const resolvedAssetHandledCounts = importReport
        ? {
            character: resolveImportReportAssetHandledCount(importReport, 'character', 'characters'),
            prop: resolveImportReportAssetHandledCount(importReport, 'prop', 'props'),
            environment: resolveImportReportAssetHandledCount(importReport, 'environment', 'environments'),
            poster: resolveImportReportAssetHandledCount(importReport, 'poster', 'posters'),
        }
        : null;
    const stage3SubtasksOk = subtaskReports.length > 0
        && subtaskReports.every((report) => String(report?.status || '').trim().toLowerCase() === 'ok');
    return {
        ...payload,
        resolvedSceneImportCount,
        resolvedAssetHandledCounts,
        stage3SubtasksOk,
    };
};

const fetchEpisodeSceneCountWithRetry = async (fetchScenesFn, episodeId, { retries = 3, delayMs = 400 } = {}) => {
    const id = Number(episodeId || 0);
    if (!id || typeof fetchScenesFn !== 'function') return 0;
    for (let attempt = 0; attempt < retries; attempt += 1) {
        const scenes = await fetchScenesFn(id).catch(() => []);
        const count = Array.isArray(scenes) ? scenes.length : 0;
        if (count > 0) return count;
        if (attempt < retries - 1) {
            await new Promise((resolve) => setTimeout(resolve, delayMs));
        }
    }
    return 0;
};

const waitForEpisodeSceneCount = async (
    fetchScenesFn,
    episodeId,
    minCount,
    { retries = 15, delayMs = 600 } = {},
) => {
    const expected = Math.max(0, Number(minCount) || 0);
    const id = Number(episodeId || 0);
    if (!id || expected <= 0 || typeof fetchScenesFn !== 'function') {
        return 0;
    }
    let lastCount = 0;
    for (let attempt = 0; attempt < retries; attempt += 1) {
        const scenes = await fetchScenesFn(id).catch(() => []);
        lastCount = Array.isArray(scenes) ? scenes.length : 0;
        if (lastCount >= expected) {
            return lastCount;
        }
        if (attempt < retries - 1) {
            await new Promise((resolve) => setTimeout(resolve, delayMs));
        }
    }
    return lastCount;
};

const resolveSceneImportAppliedCount = (importReport) => {
    if (!importReport || typeof importReport !== 'object') return 0;
    const created = Number(importReport?.importStats?.scenesCreated || 0);
    const updated = Number(importReport?.importStats?.scenesUpdated || 0);
    if (created + updated > 0) return created + updated;
    const rowsWithId = Array.isArray(importReport?.importedSceneRows)
        ? importReport.importedSceneRows.filter((row) => row?.id).length
        : 0;
    if (rowsWithId > 0) return rowsWithId;
    return Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows.length : 0;
};

const isSuccessfulSceneImportReport = (importReport) => (
    importReport
    && typeof importReport === 'object'
    && importReport.ok !== false
    && resolveSceneImportAppliedCount(importReport) > 0
);

/**
 * Resolve which orchestration Scene IDs already exist as workspace Scene rows.
 * Used by full-pipeline prechecks so existing scenes are not re-orchestrated.
 */
const resolveExistingWorkspaceSceneIds = async ({
    fetchScenesFn,
    episodeId,
    sceneIds = [],
}) => {
    const wanted = (Array.isArray(sceneIds) ? sceneIds : [])
        .map((id) => String(id || '').trim())
        .filter(Boolean);
    const existing = new Set();
    const stableEpisodeId = Number(episodeId || 0);
    if (!wanted.length || !stableEpisodeId || typeof fetchScenesFn !== 'function') {
        return existing;
    }
    const dbScenes = await fetchScenesFn(stableEpisodeId).catch(() => []);
    const rows = Array.isArray(dbScenes) ? dbScenes : [];
    for (const sceneId of wanted) {
        if (findDbSceneByPatchSceneId(rows, sceneId)) {
            existing.add(sceneId);
        }
    }
    return existing;
};

const canSkipBatchSceneImport = async ({
    fetchScenesFn,
    episodeId,
    patchSceneIds,
    liveImportedIds,
}) => {
    const patchIds = (Array.isArray(patchSceneIds) ? patchSceneIds : [])
        .map((id) => String(id || '').trim())
        .filter(Boolean);
    const liveIds = new Set(
        (Array.isArray(liveImportedIds) ? liveImportedIds : [])
            .map((id) => String(id || '').trim())
            .filter(Boolean)
    );
    if (patchIds.length <= 0 || liveIds.size < patchIds.length) return false;
    if (!patchIds.every((id) => liveIds.has(id))) return false;
    const stableEpisodeId = Number(episodeId || 0);
    if (!stableEpisodeId || typeof fetchScenesFn !== 'function') return false;
    const dbScenes = await fetchScenesFn(stableEpisodeId);
    if (!Array.isArray(dbScenes)) return false;
    return patchIds.every((patchSceneId) => dbSceneMatchesPatchSceneId(dbScenes, patchSceneId));
};

const mergeSceneImportReports = (reports = []) => {
    const validReports = (Array.isArray(reports) ? reports : []).filter((item) => item && typeof item === 'object');
    if (!validReports.length) return null;
    const mergedImportedSceneRows = validReports.flatMap((report) => (
        Array.isArray(report.importedSceneRows) ? report.importedSceneRows : []
    ));
    const mergedScenes = validReports.flatMap((report) => (
        Array.isArray(report.scenes) ? report.scenes : []
    ));
    const mergedImportedCounts = validReports.reduce((acc, report) => {
        const counts = report?.importedSubjectCounts || {};
        acc.character += Number(counts.character || 0);
        acc.prop += Number(counts.prop || 0);
        acc.environment += Number(counts.environment || 0);
        acc.poster += Number(counts.poster || 0);
        return acc;
    }, { character: 0, prop: 0, environment: 0, poster: 0 });
    return {
        ...validReports[validReports.length - 1],
        scenes: mergedScenes,
        importedSceneRows: mergedImportedSceneRows,
        importedSubjectCounts: mergedImportedCounts,
        createdSubjectItems: validReports.flatMap((report) => (
            Array.isArray(report.createdSubjectItems) ? report.createdSubjectItems : []
        )),
        skippedSubjectItems: validReports.flatMap((report) => (
            Array.isArray(report.skippedSubjectItems) ? report.skippedSubjectItems : []
        )),
        perSceneImportCount: validReports.length,
    };
};

const assertWorkspaceSceneImportComplete = ({
    importReport,
    expectedSceneCount,
    dbSceneCount,
    t,
}) => {
    const expected = Math.max(0, Number(expectedSceneCount) || 0);
    if (expected <= 0) return;
    const resolvedCount = firstPositiveFiniteNumber(
        dbSceneCount,
        resolveImportReportSceneCount(importReport, importReport?.sceneSubjectPostImportReport, dbSceneCount),
    );
    if (resolvedCount >= expected) return;
    throw new Error(t(
        `场景导入未完成：期望 ${expected} 场，工作区仅 ${resolvedCount || 0} 场。请检查导入日志后重试。`,
        `Scene import incomplete: expected ${expected} scene(s), workspace has ${resolvedCount || 0}. Check import logs and retry.`
    ));
};

const collectEpisodeSceneIdsWithShots = (shots) => {
    const sceneIds = new Set();
    (Array.isArray(shots) ? shots : []).forEach((row) => {
        const sceneId = Number(row?.scene_id || 0);
        if (Number.isFinite(sceneId) && sceneId > 0) sceneIds.add(sceneId);
    });
    return sceneIds;
};

const resolveEpisodeStoryboardCoverage = async ({
    fetchScenesFn,
    fetchEpisodeShotsFn,
    episodeId,
    allowedSceneMarkers = null,
}) => {
    const id = Number(episodeId || 0);
    if (!id || typeof fetchScenesFn !== 'function' || typeof fetchEpisodeShotsFn !== 'function') {
        return {
            sceneCount: 0,
            sceneCountWithShots: 0,
            shotCount: 0,
            missingSceneIds: [],
            ok: true,
        };
    }
    const [scenes, shots] = await Promise.all([
        fetchScenesFn(id).catch(() => []),
        fetchEpisodeShotsFn(id, { compact: true }).catch(() => []),
    ]);
    const sceneList = filterDbScenesByCanonicalMarkers(scenes, allowedSceneMarkers);
    const shotList = Array.isArray(shots) ? shots : [];
    const sceneIds = sceneList
        .map((scene) => Number(scene?.id || 0))
        .filter((sceneId) => Number.isFinite(sceneId) && sceneId > 0);
    const withShots = collectEpisodeSceneIdsWithShots(shotList);
    const missingSceneIds = sceneIds.filter((sceneId) => !withShots.has(sceneId));
    const sceneCountWithShots = sceneIds.filter((sceneId) => withShots.has(sceneId)).length;
    return {
        sceneCount: sceneIds.length,
        sceneCountWithShots,
        shotCount: shotList.length,
        missingSceneIds,
        ok: sceneIds.length <= 0 || missingSceneIds.length === 0,
    };
};

const waitForEpisodeStoryboardCoverage = async (
    fetchScenesFn,
    fetchEpisodeShotsFn,
    episodeId,
    { retries = 8, delayMs = 500, allowedSceneMarkers = null } = {},
) => {
    let last = {
        sceneCount: 0,
        sceneCountWithShots: 0,
        shotCount: 0,
        missingSceneIds: [],
        ok: true,
    };
    for (let attempt = 0; attempt < retries; attempt += 1) {
        last = await resolveEpisodeStoryboardCoverage({
            fetchScenesFn,
            fetchEpisodeShotsFn,
            episodeId,
            allowedSceneMarkers,
        });
        if (last.ok || last.sceneCount <= 0) return last;
        if (attempt < retries - 1) {
            await new Promise((resolve) => setTimeout(resolve, delayMs));
        }
    }
    return last;
};

const runAnalysisPipelineIntegrityGate = async ({
    t,
    onLog,
    fetchScenesFn,
    fetchEntitiesFn,
    fetchEpisodeShotsFn,
    projectId,
    episodeId,
    importReport,
    postImportSceneSubjectReport,
    expectedSceneCount,
    subjectIndexText,
    checkStoryboards = false,
    skipNonStoryboardChecks = false,
    allowedSceneMarkers = null,
}) => {
    const failures = [];
    let dbSceneCount = 0;
    let storyboardCoverage = null;

    if (!skipNonStoryboardChecks) {
        const resolvedSubjectIndex = String(subjectIndexText || '').trim();

        if (!resolvedSubjectIndex) {
            failures.push(t('资产清单尚未生成或尚未保存', 'Asset inventory was not generated or saved'));
        }

        const expected = Math.max(1, Number(expectedSceneCount) || 0);
        onLog?.(
            t(
                `开始本集齐套检查：期望入库 ${expected} 场，资产清单已准备就绪`,
                `Starting episode readiness check: expecting ${expected} scene(s) imported; asset inventory is ready`
            ),
            'info'
        );
        dbSceneCount = await waitForEpisodeSceneCount(
            fetchScenesFn,
            episodeId,
            expected,
            { retries: 10, delayMs: 500 },
        );
        try {
            assertWorkspaceSceneImportComplete({
                importReport,
                expectedSceneCount: expected,
                dbSceneCount,
                t,
            });
        } catch (sceneErr) {
            failures.push(String(sceneErr?.message || sceneErr || ''));
        }

        const subtaskReports = Array.isArray(postImportSceneSubjectReport?.subtaskReports)
            ? postImportSceneSubjectReport.subtaskReports
            : [];
        const failedSubtasks = subtaskReports.filter(
            (report) => String(report?.status || '').trim().toLowerCase() !== 'ok'
        );
        if (failedSubtasks.length > 0) {
            failures.push(t(
                `资产设计子任务失败：${failedSubtasks.map((item) => item?.key || 'unknown').join(', ')}`,
                `Visual asset subtasks failed: ${failedSubtasks.map((item) => item?.key || 'unknown').join(', ')}`
            ));
        }

        const supplementFailed = Number(postImportSceneSubjectReport?.supplementReport?.failedItems?.length || 0);
        if (supplementFailed > 0 && subtaskReports.length === 0) {
            failures.push(t(
                `资产入库存在 ${supplementFailed} 项失败`,
                `${supplementFailed} asset import item(s) failed`
            ));
        }

        if (projectId && fetchEntitiesFn && String(subjectIndexText || '').trim()) {
            const importedCounts = postImportSceneSubjectReport?.importedSubjectCounts || importReport?.importedSubjectCounts || {};
            const handledAssets = Number(importedCounts.character || 0)
                + Number(importedCounts.prop || 0)
                + Number(importedCounts.environment || 0)
                + Number(importedCounts.poster || 0);
            const okSubtaskCount = subtaskReports.filter(
                (report) => String(report?.status || '').trim().toLowerCase() === 'ok'
            ).length;
            if (subtaskReports.length > 0 && okSubtaskCount > 0 && handledAssets <= 0) {
                failures.push(t(
                    '资产设计子任务已完成但未检测到本轮入库记录',
                    'Visual asset subtasks completed but no assets were imported in this run'
                ));
            } else if (subtaskReports.length > 0 && okSubtaskCount <= 0 && handledAssets <= 0) {
                const entities = await fetchEntitiesFn(projectId, {
                    episode_id: Number(episodeId) || undefined,
                }).catch(() => []);
                const episodeScoped = (Array.isArray(entities) ? entities : []).filter(
                    (entity) => String(entity?.episode_id || '').trim() === String(episodeId || '').trim()
                );
                if (episodeScoped.length <= 0) {
                    failures.push(t(
                        '资产设计已完成但未检测到本集实体记录',
                        'Visual asset generation finished but no entities were found for this episode'
                    ));
                }
            }
        }
    }

    if (checkStoryboards) {
        onLog?.(
            t(
                '开始本集分镜齐套检查：按每个场景是否已有分镜核对',
                'Starting storyboard readiness check: each scene must have storyboards'
            ),
            'info'
        );
        storyboardCoverage = await waitForEpisodeStoryboardCoverage(
            fetchScenesFn,
            fetchEpisodeShotsFn,
            episodeId,
            { allowedSceneMarkers },
        );
        if (storyboardCoverage.sceneCount > 0 && !storyboardCoverage.ok) {
            const missing = Math.max(
                0,
                Number(storyboardCoverage.sceneCount || 0) - Number(storyboardCoverage.sceneCountWithShots || 0),
            );
            failures.push(t(
                `分镜未齐套：本集 ${storyboardCoverage.sceneCount} 场中仅 ${storyboardCoverage.sceneCountWithShots} 场有分镜（还差 ${missing} 场）`,
                `Storyboards incomplete: ${storyboardCoverage.sceneCountWithShots}/${storyboardCoverage.sceneCount} scene(s) have shots (${missing} still missing)`
            ));
        }
    }

    if (failures.length > 0) {
        const message = failures.filter(Boolean).join('；');
        onLog?.(t(`本集齐套检查未通过：${message}`, `Episode readiness check failed: ${message}`), 'error');
        throw new Error(t(
            `本集齐套检查未通过：${message}`,
            `Episode readiness check failed: ${message}`
        ));
    }

    if (checkStoryboards && skipNonStoryboardChecks) {
        onLog?.(
            t(
                `本集分镜齐套检查通过：${storyboardCoverage?.sceneCountWithShots || 0}/${storyboardCoverage?.sceneCount || 0} 场已有分镜。`,
                `Storyboard readiness check passed: ${storyboardCoverage?.sceneCountWithShots || 0}/${storyboardCoverage?.sceneCount || 0} scene(s) have shots.`
            ),
            'success'
        );
    } else {
        const storyboardSuffix = checkStoryboards && storyboardCoverage
            ? t(
                `；分镜 ${storyboardCoverage.sceneCountWithShots}/${storyboardCoverage.sceneCount} 场已齐`,
                `; storyboards ready for ${storyboardCoverage.sceneCountWithShots}/${storyboardCoverage.sceneCount} scene(s)`
            )
            : '';
        onLog?.(
            t(
                `本集齐套检查通过：已入库 ${dbSceneCount} 场，资产清单与资产设计均已完成${storyboardSuffix}。`,
                `Episode readiness check passed: ${dbSceneCount} scene(s) imported; asset inventory and asset design are complete${storyboardSuffix}.`
            ),
            'success'
        );
    }
    return { dbSceneCount, storyboardCoverage, ok: true };
};

const ANALYSIS_FLOW_HISTORY_CAP = 500;
const ANALYSIS_DETAIL_LOG_CAP = 500;

const getAnalysisSessionStorageKey = (episodeId) => {
    const id = Number(episodeId || 0);
    return id > 0 ? `aistory:analysis-session:${id}` : '';
};

const loadAnalysisSessionSnapshot = (episodeId) => {
    try {
        const key = getAnalysisSessionStorageKey(episodeId);
        if (!key || !window?.localStorage) return null;
        let raw = window.localStorage.getItem(key);
        if (!raw && window?.sessionStorage) {
            raw = window.sessionStorage.getItem(key);
            if (raw) {
                window.localStorage.setItem(key, raw);
                window.sessionStorage.removeItem(key);
            }
        }
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === 'object' ? parsed : null;
    } catch (_) {
        return null;
    }
};

const slimAnalysisUiReportForSnapshot = (uiReport) => {
    if (!uiReport || typeof uiReport !== 'object') return null;
    return {
        status: uiReport.status,
        startedAt: uiReport.startedAt,
        durationMs: uiReport.durationMs,
        warning: uiReport.warning,
        error: uiReport.error,
        reviewIssues: Array.isArray(uiReport.reviewIssues) ? uiReport.reviewIssues : [],
        runTag: uiReport.runTag,
        resolvedSceneImportCount: uiReport.resolvedSceneImportCount,
        resolvedAssetHandledCounts: uiReport.resolvedAssetHandledCounts,
        stage3SubtasksOk: uiReport.stage3SubtasksOk,
        storyboardAutoStarted: Boolean(uiReport.storyboardAutoStarted),
        storyboardTaskProgress: normalizeStoryboardTaskProgress(uiReport.storyboardTaskProgress),
    };
};

const saveAnalysisSessionSnapshot = (episodeId, snapshot) => {
    try {
        const key = getAnalysisSessionStorageKey(episodeId);
        if (!key || !window?.localStorage || !snapshot || typeof snapshot !== 'object') return;
        window.localStorage.setItem(key, JSON.stringify(snapshot));
        try {
            window.sessionStorage?.removeItem(key);
        } catch (_) {
            // Ignore sessionStorage cleanup failures.
        }
    } catch (_) {
        // Ignore localStorage failures.
    }
};

const clearAnalysisSessionProgressSnapshot = (episodeId) => {
    try {
        const id = Number(episodeId || 0);
        if (!id) return;
        const prev = loadAnalysisSessionSnapshot(id);
        if (!prev || typeof prev !== 'object') return;
        saveAnalysisSessionSnapshot(id, {
            ...prev,
            progressUi: {
                dismissed: false,
                flowStatus: { phase: 'idle', message: '' },
                flowHistory: [],
                detailLogs: [],
                uiReport: null,
            },
            savedAt: Date.now(),
        });
    } catch (_) {
        // Ignore localStorage failures.
    }
};

/** `endedAt: null` must NOT count as finished — Number(null) === 0 is finite. */
const hasAnalysisHistoryEndedAt = (item) => {
    const endedAt = Number(item?.endedAt);
    return Number.isFinite(endedAt) && endedAt > 0;
};

/** Canonical pipeline order for progress UI + final report (5 stages). */
const ANALYSIS_LIVE_STEP_ORDER = [
    'script_opt',      // 1. 剧本统筹
    'extract_assets',  // 2. 资产清单
    'scene_beats',     // 3. 场景编排
    'assets_gen',      // 4. 资产设计
    'storyboard',      // 5. 分镜生成
];

const ANALYSIS_STAGE_LABELS = {
    script_opt: { zh: '剧本统筹', en: 'Script Coordination' },
    extract_assets: { zh: '资产清单', en: 'Asset Inventory' },
    scene_beats: { zh: '场景编排', en: 'Scene Orchestration' },
    assets_gen: { zh: '资产设计', en: 'Asset Design' },
    storyboard: { zh: '分镜生成', en: 'Storyboard Generation' },
};

const getAnalysisStageLabel = (stepKey, tFn) => {
    const meta = ANALYSIS_STAGE_LABELS[String(stepKey || '').trim()] || null;
    if (!meta) return String(stepKey || '');
    return typeof tFn === 'function' ? tFn(meta.zh, meta.en) : meta.zh;
};

/** Soften technical pipeline logs for the system log / progress history. */
const toBusinessAnalysisLogMessage = (rawMessage, tFn = (zh) => zh) => {
    let text = String(rawMessage || '').trim();
    if (!text) return '';
    const t = typeof tFn === 'function' ? tFn : (zh) => zh;

    // Drop ultra-noisy internal writeback / debug lines from the user-facing stream.
    if (/^\[(?:Analysis Writeback|Stage2\.2 Debug|Stage 3 Debug|Asset Gen Tracking)\]/i.test(text)) {
        return '';
    }

    const replacements = [
        [/\[Integrity Gate\]/gi, t('[齐套检查]', '[Readiness check]')],
        [/\[Analysis Resume\]/gi, t('[继续分析]', '[Resume analysis]')],
        [/\[Auto Zero Report Rerun\]/gi, t('[自动补齐]', '[Auto refill]')],
        [/\[Scene Units Sync\]/gi, t('[场景同步]', '[Scene sync]')],
        [/\[Stage 2 Asset Index\]/gi, t('[资产清单]', '[Asset inventory]')],
        [/\[Stage 1 Adapted Script\]/gi, t('[剧本统筹]', '[Script coordination]')],
        [/\[Stage 3 Asset Design\]/gi, t('[资产设计]', '[Asset design]')],
        [/\[Stage\s*2\.1\]/gi, t('[资产清单]', '[Asset inventory]')],
        [/\[Stage\s*2\.2\]/gi, t('[场景编排]', '[Scene orchestration]')],
        [/\[Stage\s*3\]/gi, t('[资产设计]', '[Asset design]')],
        [/\[Stage\s*1\]/gi, t('[剧本统筹]', '[Script coordination]')],
        [/\bStage\s*2\.1\b/gi, t('资产清单', 'asset inventory')],
        [/\bStage\s*2\.2\b/gi, t('场景编排', 'scene orchestration')],
        [/\bStage\s*3\b/gi, t('资产设计', 'asset design')],
        [/\bStage\s*1\b/gi, t('剧本统筹', 'script coordination')],
        [/\bSubject Index\b/gi, t('资产清单', 'asset inventory')],
        [/\bscene_markdown_by_scene\b/gi, t('分场场景编排', 'per-scene orchestration')],
        [/\bscene_markdown\b/gi, t('场景编排内容', 'scene orchestration content')],
        [/\bscript_optimization\b/gi, t('剧本统筹', 'script coordination')],
        [/\bassets_extraction\b/gi, t('资产清单', 'asset inventory')],
        [/\basset_design_environment\b/gi, t('环境资产设计', 'environment asset design')],
        [/\basset_design_character\b/gi, t('角色资产设计', 'character asset design')],
        [/\basset_design_prop\b/gi, t('道具资产设计', 'prop asset design')],
        [/\basset_design(?:_json)?\b/gi, t('资产设计结果', 'asset design result')],
        [/\bstoryboard_generation\b/gi, t('分镜生成', 'storyboard generation')],
        [/\bscene_beats\b/gi, t('场景编排', 'scene orchestration')],
        [/\bcover_poster\b/gi, t('封面海报', 'cover poster')],
        [/\bsubjects[_\s-]?json\b/gi, t('资产结构化结果', 'asset structured result')],
        [/\bScenes Table\b/gi, t('场景表', 'scenes table')],
        [/\bScene ID\b/gi, t('场景编号', 'scene ID')],
        [/\bBeats\b/g, t('节拍', 'beats')],
        [/\bLLM\b/gi, t('AI', 'AI')],
        [/\bJSON\b/g, t('结构化结果', 'structured result')],
        [/\bAPI\b/g, t('服务接口', 'service')],
        [/Persisting clean .+ immediately after return\.\.\./i, t('正在保存资产清单…', 'Saving asset inventory...')],
        [/Persisting per-scene .+ immediately after parallel beats return\.\.\./i, t('正在保存各场场景编排结果…', 'Saving per-scene orchestration...')],
        [/Submitting .+ \(Asset Extraction\)\.\.\./i, t('正在生成资产清单…', 'Generating asset inventory...')],
        [/Cleared existing episode scenes before .+\./i, t('已清空本集旧场景，准备重新导入。', 'Cleared previous scenes in this episode before re-import.')],
        [/Pre-import .+ purge warning:/i, t('导入前清理提示：', 'Pre-import cleanup notice:')],
        [/Failed to persist clean .+:/i, t('保存资产清单失败：', 'Failed to save asset inventory:')],
        [/Failed to save asset index edit:/i, t('保存资产清单修改失败：', 'Failed to save asset inventory edits:')],
        [/Failed to save adapted script edit:/i, t('保存剧本统筹修改失败：', 'Failed to save script coordination edits:')],
        [/Failed to save per-scene scene markdown:/i, t('保存分场场景编排失败：', 'Failed to save per-scene orchestration:')],
        [/Failed to clear per-scene scene markdown:/i, t('清理分场场景编排失败：', 'Failed to clear per-scene orchestration:')],
        [/Saved manual edit \(len=\d+\)/i, t('已保存手动修改。', 'Manual edits saved.')],
        [/Saved manual beats edit \(len=\d+\)/i, t('已保存剧本统筹修改。', 'Script coordination edits saved.')],
        [/Scene markdown precheck skipped:/i, t('场景编排预检已跳过：', 'Scene orchestration precheck skipped:')],
        [/Scene markdown precheck passed:/i, t('场景编排预检通过：', 'Scene orchestration precheck passed:')],
        [/Scene markdown repair:/i, t('场景编排修复：', 'Scene orchestration repair:')],
        [/backend scene orchestration enabled:/i, t('已启用按场场景编排：', 'Per-scene orchestration enabled:')],
        [/Skipped duplicate Stage 3 asset-design trigger/i, t('已跳过重复的资产设计触发', 'Skipped duplicate asset-design trigger')],
        [/automatic asset design already completed successfully for this episode run/i, t('本轮自动资产设计已成功完成', 'automatic asset design already completed for this episode run')],
        [/Cleared stale phase-2 marker/i, t('已清理过期的资产设计标记', 'Cleared stale asset-design marker')],
        [/Cleared stale scene_beats marker/i, t('已清理过期的场景编排标记', 'Cleared stale scene-orchestration marker')],
        [/未生成或未持久化/g, t('尚未生成或尚未保存', 'was not generated or saved')],
        [/完整性检查通过/g, t('齐套检查通过', 'readiness check passed')],
        [/分析管线完整性检查未通过/g, t('本集齐套检查未通过', 'episode readiness check failed')],
    ];

    replacements.forEach(([pattern, value]) => {
        text = text.replace(pattern, value);
    });

    // Soften leftover "field=xxx len=yyy" style fragments.
    text = text
        .replace(/\bfield=\S+/gi, '')
        .replace(/\braw_len=\d+/gi, '')
        .replace(/\badaptation_len=\d+/gi, '')
        .replace(/\bsubject_index_len=\d+/gi, '')
        .replace(/\bbundle_len=\d+/gi, '')
        .replace(/\bmerged_chars=\d+/gi, '')
        .replace(/\bsource=\S+/gi, '')
        .replace(/\s{2,}/g, ' ')
        .trim();

    return text;
};

const normalizeAnalysisLivePhase = (phase) => {
    const key = String(phase || '').trim().toLowerCase();
    if (key === 'supplement') return 'assets_gen';
    if (key === 'running') return 'script_opt';
    // Terminal "completed" means all 5 stages finished; treat as past storyboard.
    if (key === 'completed') return 'storyboard';
    return key;
};

/** During a live run, ignore leftover artifacts from stages not yet reached. */
const canTrustStageArtifactDuringLiveRun = (phase, stepKey, { isLive = false } = {}) => {
    if (!isLive) return true;
    const rawPhase = String(phase || '').trim().toLowerCase();
    if (['failed', 'warning', 'idle'].includes(rawPhase)) return true;
    if (rawPhase === 'completed') return true;
    const normalizedPhase = normalizeAnalysisLivePhase(phase);
    const phaseIdx = ANALYSIS_LIVE_STEP_ORDER.indexOf(normalizedPhase);
    const stepIdx = ANALYSIS_LIVE_STEP_ORDER.indexOf(String(stepKey || '').trim());
    if (phaseIdx < 0 || stepIdx < 0) return false;
    // After 2.1, scene orchestration and asset design run concurrently.
    if (phaseIdx >= 2 && (stepKey === 'scene_beats' || stepKey === 'assets_gen')) return true;
    if (stepKey === 'script_opt' || stepKey === 'extract_assets') return phaseIdx > stepIdx;
    return phaseIdx > stepIdx;
};

const isAnalysisLiveStepActive = (phase, stepKey, { isLive = false } = {}) => {
    if (!isLive) return false;
    const rawPhase = String(phase || '').trim().toLowerCase();
    if (['failed', 'warning', 'completed', 'idle'].includes(rawPhase)) return false;
    const normalizedPhase = normalizeAnalysisLivePhase(phase);
    const phaseIdx = ANALYSIS_LIVE_STEP_ORDER.indexOf(normalizedPhase);
    const stepIdx = ANALYSIS_LIVE_STEP_ORDER.indexOf(String(stepKey || '').trim());
    if (phaseIdx < 0 || stepIdx < 0) return false;
    if (phaseIdx === stepIdx) return true;
    // Mirror concurrent fan-out after Subject Index (scene orchestration ∥ asset design).
    if (phaseIdx === 2 && stepKey === 'assets_gen') return true;
    if (phaseIdx === 3 && stepKey === 'scene_beats') return true;
    return false;
};

const isStoryboardTaskProgressSettled = (progressValue) => {
    const progress = normalizeStoryboardTaskProgress(progressValue);
    const started = Number(progress.started || 0);
    if (started <= 0) return false;
    const running = Number(progress.running || 0);
    const waiting = Number(progress.waiting || 0);
    const finished = Number(progress.completed || 0) + Number(progress.failed || 0);
    return running <= 0 && waiting <= 0 && finished >= started;
};

const isStoryboardProgressUnresolved = (progressValue) => {
    const progress = normalizeStoryboardTaskProgress(progressValue);
    const started = Number(progress.started || 0);
    if (started <= 0) return false;
    return !isStoryboardTaskProgressSettled(progress);
};

const isPersistedAnalysisProgressRunning = (progressUi) => {
    if (!progressUi || progressUi.dismissed === true) return false;
    const flowStatus = (progressUi.flowStatus && typeof progressUi.flowStatus === 'object')
        ? progressUi.flowStatus
        : { phase: 'idle', message: '' };
    const uiReport = (progressUi.uiReport && typeof progressUi.uiReport === 'object') ? progressUi.uiReport : null;
    const flowHistory = Array.isArray(progressUi.flowHistory) ? progressUi.flowHistory : [];
    const phase = String(flowStatus?.phase || 'idle').trim().toLowerCase();
    const reportStatus = String(uiReport?.status || '').trim().toLowerCase();
    if (reportStatus === 'running') return true;
    // Storyboard panel can linger on phase=storyboard after all shots settle; that is not a live run.
    if (phase === 'storyboard' && isStoryboardTaskProgressSettled(uiReport?.storyboardTaskProgress)) {
        return false;
    }
    if (phase && !['idle', 'completed', 'failed', 'warning'].includes(phase)) return true;
    if (flowHistory.some((item) => !hasAnalysisHistoryEndedAt(item))) return true;
    return false;
};

const hasPersistedEntityDesignPayload = (rawText) => {
    const text = String(rawText || '').trim();
    if (!text) return false;
    return /"characters"\s*:\s*\[|"props"\s*:\s*\[|"environments"\s*:\s*\[|"posters"\s*:\s*\[|"covers"\s*:\s*\[/i.test(text);
};

